export const CATEGORY_ICON: Record<string, string> = {"payroll": "banknotes", "gig_income": "briefcase", "tax_refund": "receipt-refund", "interest": "arrow-trending-up", "dividends": "chart-pie", "internal_transfer": "arrows-right-left", "family_transfer": "users", "app_transfer": "device-phone-mobile", "other_transfer": "arrow-path", "credit_card_payment": "credit-card", "loan_payment": "building-library", "investment_contribution": "chart-bar", "retirement_contribution": "presentation-chart-line", "savings_contribution": "archive-box", "food_and_drink": "cake", "groceries": "shopping-cart", "shopping": "shopping-bag", "entertainment": "film", "transportation": "truck", "travel": "paper-airplane", "rent_and_utilities": "home-modern", "home": "home", "medical": "heart", "personal_care": "sparkles", "services": "wrench-screwdriver", "government": "building-office-2", "bank_fees": "receipt-percent", "gear": "camera", "other_spending": "ellipsis-horizontal-circle"};

/** A solid Heroicon by name. */
export function HeroIcon({ name, className = "" }: { name: string; className?: string }) {
  const body = SOLID[name];
  if (!body) return null;
  return (
    <svg viewBox="0 0 24 24" fill="currentColor" className={className} aria-hidden="true">
      {body}
    </svg>
  );
}

/** The site's paired sidebar icon: outline at rest, solid on hover or when active. */
export function PairedIcon({ name, className = "" }: { name: string; className?: string }) {
  return (
    <span className={`ico ${className}`} aria-hidden="true">
      <svg className="ico-line" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5">{OUTLINE[name] ?? SOLID[name]}</svg>
      <svg className="ico-fill" viewBox="0 0 24 24" fill="currentColor">{SOLID[name]}</svg>
    </span>
  );
}

/** The icon for a bucket id. */
export function BucketIcon({ id, className = "" }: { id: string; className?: string }) {
  return <HeroIcon name={BUCKET_ICON[id] ?? "archive-box"} className={className} />;
}

/** The icon for a category id, falling back to the generic "other" glyph. */
export function CategoryIcon({ id, className = "" }: { id: string | null | undefined; className?: string }) {
  return <HeroIcon name={CATEGORY_ICON[id ?? ""] ?? "ellipsis-horizontal-circle"} className={className} />;
}
